do $$ declare acme_id uuid; globex_id uuid; acme_user uuid := '00000000-0000-4000-8000-000000000001'; globex_user uuid := '00000000-0000-4000-8000-000000000002'; begin select id into acme_id from public.companies where slug='acme'; select id into globex_id from public.companies where slug='globex'; insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values(acme_user,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','recruiter@acme.test',crypt('password123',gen_salt('bf')),now(),'{}','{"full_name":"Alex Recruiter"}',now(),now()),(globex_user,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','recruiter@globex.test',crypt('password123',gen_salt('bf')),now(),'{}','{"full_name":"Sam Recruiter"}',now(),now()) on conflict(id) do nothing; insert into public.profiles(id,company_id,full_name) values(acme_user,acme_id,'Alex Recruiter'),(globex_user,globex_id,'Sam Recruiter') on conflict(id) do nothing; end $$;
